      de: ["Landwirtschaft", "Rogaland", "Zentrum", "Flachland"],
      hu: ["Mezőgazdaság", "Rogaland", "Központ", "Alföld"],
      ro: ["Agricultură", "Rogaland", "Centru", "Câmpie"],
      en: ["Agriculture", "Rogaland", "Center", "Plains"],
      es: ["Agricultura", "Rogaland", "Centro", "Llanura"],
      pt: ["Agricultura", "Rogaland", "Centro", "Planície"],
